    'Estados Unidos': 'United States',
    'Reino Unido': 'United Kingdom',
    'Italia': 'Italy',
    'Corea del Sur': 'South Korea'
}
df['Country'] = df['Country'].replace(country_map)

# Clean Condition
condition_map = {
    'Usado': 'Used',
    'Nuevo': 'New',
    'Novo': 'New',
    'Caja abierta': 'Open box',
    '--': 'Unknown'
}
df['condition'] = df['condition'].replace(condition_map)

# Combine Refurbished
def group_condition(c):
    if 'Refurbished' in c:
        return 'Refurbished'
    if c in ['Open box', 'New other']:
        return 'Open box/Other'
    if c == 'For parts or not working':
        return 'For parts'
    return c

df['cond_group'] = df['condition'].apply(group_condition)

# 3. Compute KPIs and Metrics

# Overview
total_listings = len(df)
brand_counts = df['brand'].value_counts()
cond_counts = df['cond_group'].value_counts()
country_counts = df['Country'].value_counts()

# Brand Pricing
brand_pricing = df.groupby('brand')['price'].agg(['count', 'mean', 'median', 'min', 'max']).reset_index()
brand_pricing['price_spread'] = brand_pricing['max'] - brand_pricing['min']

# Geo Pricing
geo_brand = df.groupby(['Country', 'brand'])['price'].median().reset_index()
# Filter to countries with at least 10 listings per brand to avoid outliers
country_brand_counts = df.groupby(['Country', 'brand']).size().reset_index(name='count')
geo_brand = pd.merge(geo_brand, country_brand_counts, on=['Country', 'brand'])
geo_brand_valid = geo_brand[geo_brand['count'] >= 5] # At least 5 listings for stable median

# Geo Spread KPI
geo_pivot = geo_brand_valid.pivot(index='Country', columns='brand', values='price')
geo_spread_kpi = {}
for b in ['Apple', 'Garmin', 'Samsung']:
    if b in geo_pivot.columns:
        valid_prices = geo_pivot[b].dropna()
        if len(valid_prices) > 0:
            geo_spread_kpi[b] = valid_prices.max() - valid_prices.min()

# Case Size Premium
df_size = df.dropna(subset=['Case_Size_mm'])
size_corr = df_size.groupby('brand').apply(lambda x: x['Case_Size_mm'].corr(x['price'])).to_dict()
# Overall correlation
overall_size_corr = df_size['Case_Size_mm'].corr(df_size['price'])

# Power Seller Behavior
seller_counts = df['Seller_ID'].value_counts()
top_5_pct_cutoff = int(len(seller_counts) * 0.05)
power_sellers = seller_counts.head(top_5_pct_cutoff).index
df['is_power_seller'] = df['Seller_ID'].isin(power_sellers)

power_seller_share = df['is_power_seller'].mean() * 100

seller_pricing = df.groupby(['brand', 'is_power_seller'])['price'].median().reset_index()
power_pricing_pivot = seller_pricing.pivot(index='brand', columns='is_power_seller', values='price')
power_pricing_pivot.columns = ['Regular Seller Median', 'Power Seller Median']

# New vs Used Premium
new_used_median = df[df['cond_group'].isin(['New', 'Used'])].groupby(['brand', 'cond_group'])['price'].median().unstack()
new_used_median['Premium %'] = ((new_used_median['New'] - new_used_median['Used']) / new_used_median['Used']) * 100

# 4. Generate Visuals (Plotly HTML snippets)
config = {'displayModeBar': False}

