fig_brand = px.pie(names=brand_counts.index, values=brand_counts.values, hole=0.4, title="Listings by Brand", color_discrete_sequence=px.colors.qualitative.Pastel)
fig_brand.update_layout(margin=dict(t=40, b=0, l=0, r=0))
html_brand = fig_brand.to_html(full_html=False, include_plotlyjs=False, config=config)

# Fig 2: Brand Price Boxplot
