fig_price.update_layout(margin=dict(t=40, b=0, l=0, r=0), showlegend=False, yaxis_title="Price (USD) - Log Scale")
html_price = fig_price.to_html(full_html=False, include_plotlyjs=False, config=config)

# Fig 3: Geo Pricing Heatmap
