fig_geo = px.imshow(geo_heatmap_data, text_auto=".0f", aspect="auto", title="Median Price by Country and Brand (USD)", color_continuous_scale="RdYlGn_r")
fig_geo.update_layout(margin=dict(t=40, b=0, l=0, r=0))
html_geo = fig_geo.to_html(full_html=False, include_plotlyjs=False, config=config)

# Fig 4: Case Size vs Price Scatter
